@Composable
fun DailyGlowNavigationBar(selected: String, onSelect: (String) -> Unit) {
    Row(
        modifier = Modifier.fillMaxWidth().background(LifePaper).padding(horizontal = 10.dp, vertical = 8.dp),
        horizontalArrangement = Arrangement.SpaceEvenly,
        verticalAlignment = Alignment.CenterVertically
    ) {
        listOf("today" to "今日", "training" to "训练", "life" to "生活").forEach { (key, label) ->
            val active = selected == key
            Text(
                text = (if (active) "● " else "") + label,
                modifier = Modifier.clickable { onSelect(key) }.padding(horizontal = 14.dp, vertical = 8.dp),
                color = if (active) LifeBlue else LifeInk.copy(alpha = .72f),
                fontWeight = if (active) FontWeight.Bold else FontWeight.Normal,
                fontSize = 14.sp
            )
        }
    }
}

@Composable
fun TodayLandingScreen(trainingTitle: String, completed: Int, onTraining: () -> Unit, onLife: () -> Unit, context: Context) {
    val prefs = remember(context) { context.getSharedPreferences("dailyglow_life", Context.MODE_PRIVATE) }
    val date = LocalDate.now().toString()
    val water = remember(date) { prefs.getInt("water_$date", 0) }
    LazyColumn(
        modifier = Modifier.fillMaxSize().background(LifePaper),
        contentPadding = PaddingValues(18.dp),
        verticalArrangement = Arrangement.spacedBy(14.dp)
    ) {
        item {
            Text("今日", color = LifeBlue, fontSize = 28.sp, fontWeight = FontWeight.Bold)
            Text(LocalDate.now().toString(), color = LifeInk.copy(alpha = .72f), fontSize = 14.sp)
        }
        item { LifeCardBlock("今日训练", trainingTitle.ifBlank { "今日训练计划" }, "已完成 $completed 项", "开始训练", LifePeach, onTraining) }
        item { LifeCardBlock("生活记录", "喝水 $water / 8 杯 · 日记 · 衣橱 · 流水", "拾光小队与朋友们陪伴共用记录", "打开生活区", LifeSage, onLife) }
        item { Text("记录按日期保存在这台设备上。", color = LifeInk.copy(alpha = .68f), fontSize = 13.sp) }
    }
}

@Composable
private fun LifeCardBlock(title: String, body: String, foot: String, action: String, tint: Color, onClick: () -> Unit) {
    Card(
        modifier = Modifier.fillMaxWidth().clickable(onClick = onClick),
        shape = RoundedCornerShape(24.dp),
        colors = CardDefaults.cardColors(containerColor = tint.copy(alpha = .72f))
    ) {
        Column(Modifier.padding(18.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
            Text(title, color = LifeBlue, fontWeight = FontWeight.Bold, fontSize = 19.sp)
            Text(body, color = LifeInk, fontSize = 16.sp)
            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.SpaceBetween, modifier = Modifier.fillMaxWidth()) {
                Text(foot, color = LifeInk.copy(alpha = .72f), fontSize = 12.sp)
                Text(action + "  ›", color = LifeBlue, fontWeight = FontWeight.SemiBold, fontSize = 14.sp)
            }
        }
    }
}

@Composable
fun DailyLifeHub(context: Context, trainingTitle: String, trainingCompleted: Int, onTraining: () -> Unit, onExit: () -> Unit = {}) {
    val prefs = remember(context) { context.getSharedPreferences("dailyglow_life", Context.MODE_PRIVATE) }
    var selectedDate by remember { mutableStateOf(LocalDate.now()) }
    val date = selectedDate.toString()
    val isToday = selectedDate == LocalDate.now()
    var section by remember { mutableStateOf("home") }
    var companion by remember { mutableStateOf(prefs.getString("companion", "拾光小队") ?: "拾光小队") }
    var water by remember(date) { mutableIntStateOf(prefs.getInt("water_$date", 0)) }
    var cupMl by remember(date) { mutableIntStateOf(prefs.getInt("water_cup_ml_$date", 300)) }
    var diary by remember(date) { mutableStateOf(prefs.getString("diary_$date", "") ?: "") }
    var outfit by remember(date) { mutableStateOf(prefs.getString("outfit_$date", "") ?: "") }
    var outfitStyle by remember(date) { mutableStateOf(prefs.getString("outfit_style_$date", "日常") ?: "日常") }
    var closet by remember { mutableStateOf(prefs.getString("closet_items", "") ?: "") }
    var mood by remember(date) { mutableStateOf(prefs.getString("mood_$date", "") ?: "") }
    var expenseSource by remember { mutableStateOf("支付宝") }
    var expenseCategory by remember { mutableStateOf("") }
    var amount by remember { mutableStateOf("") }
    var note by remember { mutableStateOf("") }
    var transactions by remember(date) { mutableStateOf(prefs.getString("transactions_$date", "") ?: "") }
    var saved by remember { mutableStateOf(false) }
    var ocrText by remember { mutableStateOf("") }
    var ocrStatus by remember { mutableStateOf("") }
    var showWaterCustom by remember { mutableStateOf(false) }
    var customWaterInput by remember { mutableStateOf("") }

    val receiptPicker = rememberLauncherForActivityResult(PickVisualMedia()) { uri ->
        if (uri == null) return@rememberLauncherForActivityResult
        ocrText = ""; ocrStatus = "正在本机识别截图…"
        try {
            val recognizer = TextRecognition.getClient(ChineseTextRecognizerOptions.Builder().build())
            recognizer.process(InputImage.fromFilePath(context, uri))
                .addOnSuccessListener { result ->
                    ocrText = result.text
                    val candidates = ocrAmountCandidates(result.text)
                    if (candidates.size == 1) {
                        amount = String.format(Locale.US, "%.2f", candidates.single())
                        ocrStatus = "识别完成，请核对金额、账户和分类后再保存。"
                    } else {
                        ocrStatus = if (result.text.isBlank()) "没有识别出文字，请换一张清晰截图。" else "已提取文字；金额不唯一，请核对后手动填写。"
                    }
                    recognizer.close()
                }.addOnFailureListener {
                    ocrStatus = "截图识别失败，请手动填写流水。"; recognizer.close()
                }
        } catch (_: Exception) { ocrStatus = "无法读取这张截图，请重新选择或手动填写。" }
    }

    val monthPrefix = "transactions_${selectedDate.year}-${selectedDate.monthValue.toString().padStart(2, '0')}"
    val monthLines = prefs.all.filterKeys { it.startsWith(monthPrefix) }.values.filterIsInstance<String>().flatMap { it.lines() }.filter(String::isNotBlank)
    val monthlyTotal = monthLines.sumOf(::expenseAmount)
    val categoryTotals = monthLines.groupBy { it.split("·").getOrNull(1)?.trim()?.takeIf(String::isNotBlank) ?: "未分类" }
        .mapValues { (_, rows) -> rows.sumOf(::expenseAmount) }.toList().sortedByDescending { it.second }
    val meals = listOf("早餐", "午餐", "晚餐").count { (prefs.getString("meal_${it}_$date", "") ?: "").isNotBlank() }
    val habits = listOf("habit_move_$date", "habit_sleep_$date").count { prefs.getBoolean(it, false) }
    val active = when (section) {
        "diary" -> "records"; "water" -> "happiness"; "wardrobe" -> "wardrobe"; "ledger", "add_expense" -> "ledger"; else -> "today"
    }

    Column(Modifier.fillMaxSize().background(LifePaper)) {
        LazyColumn(Modifier.weight(1f), contentPadding = PaddingValues(horizontal = 13.dp, vertical = 6.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
            item { LifePreviewBanner(section, companion) }
            item { LifeDateStrip(selectedDate, isToday, { selectedDate = selectedDate.minusDays(1) }, { if (!isToday) selectedDate = selectedDate.plusDays(1) }) }
            when (section) {
                "home" -> {
                    item {
                        Row(Modifier.fillMaxWidth().background(LifeCard, RoundedCornerShape(22.dp)).border(1.dp, Color(0xFFF0E7DE), RoundedCornerShape(22.dp)).padding(4.dp)) {
                            listOf("拾光小队", "朋友们陪伴").forEach { mode ->
                                Text((if (mode == "拾光小队") "🐾  " else "♧  ") + mode,
                                    Modifier.weight(1f).background(if (companion == mode) LifePeach else Color.Transparent, RoundedCornerShape(20.dp))
                                        .clickable { companion = mode; prefs.edit().putString("companion", mode).apply() }.padding(vertical = 10.dp),
                                    color = LifeBlue, fontSize = 13.sp, fontWeight = if (companion == mode) FontWeight.SemiBold else FontWeight.Normal, textAlign = TextAlign.Center)
                            }
                        }
                    }
                    item {
                        Row(Modifier.fillMaxWidth().background(Color(0xFFE8EFE7), RoundedCornerShape(16.dp)).clickable(onClick = onTraining).padding(horizontal = 12.dp, vertical = 9.dp), verticalAlignment = Alignment.CenterVertically) {
                            Text("🏃", fontSize = 18.sp)
                            Column(Modifier.weight(1f).padding(start = 8.dp)) {
                                Text("DailyGlow · 今日训练", color = LifeBlue, fontSize = 13.sp, fontWeight = FontWeight.SemiBold)
                                Text("$trainingTitle · 已完成 $trainingCompleted 项", color = LifeInk.copy(alpha = .78f), fontSize = 10.sp)
                            }
                            Text("开始 ›", color = LifeBlue, fontSize = 12.sp)
                        }
                    }
                    item { Row(horizontalArrangement = Arrangement.spacedBy(7.dp)) {
                        LifeFeatureTile("生活邮局", if (companion == "拾光小队") AnimalDiaryArt else DiaryHeroArt, Modifier.weight(1f)) { section = "diary" }
                        LifeFeatureTile("今日小确幸", if (companion == "拾光小队") AnimalWaterArt else WaterHeroArt, Modifier.weight(1f)) { section = "water" }
                    } }
                    item { Row(horizontalArrangement = Arrangement.spacedBy(7.dp)) {
                        LifeFeatureTile("衣橱裁缝铺", if (companion == "拾光小队") AnimalWardrobeArt else WardrobeHeroArt, Modifier.weight(1f)) { section = "wardrobe" }
                        LifeFeatureTile("每日流水", if (companion == "拾光小队") AnimalLedgerArt else LedgerHeroArt, Modifier.weight(1f)) { section = "ledger" }
                    } }
                    item {
                        LifePaperCard {
                            LifeSectionTitle("🌱  今日进度")
                            Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                LifeProgress("💧", "$water/8", "喝水", water / 8f, Color(0xFF79C1E9), Modifier.weight(1f))
                                LifeProgress("🍚", "$meals/3", "三餐", meals / 3f, Color(0xFFF2A877), Modifier.weight(1f))
                                LifeProgress("✓", "$habits/2", "日常习惯", habits / 2f, Color(0xFF91BE91), Modifier.weight(1f))
                            }
                        }
                    }
                }
                "diary" -> {
                    item { LifeNote("今天也给自己留一点空白。", "不管认真努力的时刻，还是偶尔发呆的片刻，都值得被温柔记住。", LifePeach) }
                    item { LifePaperCard {
                        Text("给今天的我：", color = LifeBlue, fontSize = 18.sp, fontWeight = FontWeight.SemiBold)
                        BasicTextField(value = diary, onValueChange = { diary = it; saved = false },
                            modifier = Modifier.fillMaxWidth().height(190.dp).background(Color(0xFFFFFCF7), RoundedCornerShape(12.dp)).padding(12.dp),
                            textStyle = androidx.compose.ui.text.TextStyle(color = LifeBlue, fontSize = 15.sp, lineHeight = 25.sp),
                            decorationBox = { inner -> Box { if (diary.isBlank()) Text("今天的你，已经做了很多了。\n把想说的话慢慢写下来……", color = LifeBlue.copy(alpha = .48f), fontSize = 15.sp, lineHeight = 25.sp); inner() } })
                        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.End) {
                            Button(onClick = { prefs.edit().putString("diary_$date", diary).apply(); saved = true }, colors = ButtonDefaults.buttonColors(containerColor = LifePeach)) { Text(if (saved) "已收好这封信" else "收好这封信", color = LifeBlue) }
                        }
                    } }
                    item { LifePaperCard {
                        LifeSectionTitle("此刻的心情")
                        Row(horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                            listOf("开心", "平静", "充实", "放松", "有点累").forEachIndexed { i, label ->
                                val tint = listOf(LifePeach, Color(0xFFDCEAF0), Color(0xFFF4E2CE), LifeSage, Color(0xFFF2DAD6))[i]
                                Text(label, Modifier.weight(1f).background(tint.copy(alpha = if (mood == label) .9f else .42f), RoundedCornerShape(11.dp))
                                    .clickable { mood = label; prefs.edit().putString("mood_$date", label).apply() }.padding(vertical = 10.dp), color = LifeBlue, fontSize = 10.sp, textAlign = TextAlign.Center)
                            }
                        }
                    } }
                    item { LifePaperCard {
                        Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.SpaceBetween) {
                            Column { LifeSectionTitle("💧  喝点水吧"); Text("小口喝水，也是在照顾自己呀。", color = LifeInk.copy(alpha = .72f), fontSize = 11.sp) }
                            Text("$water / 8 杯", color = LifeBlue, fontWeight = FontWeight.Bold)
                        }
                        Button(onClick = { if (water < 8) water++; prefs.edit().putInt("water_$date", water).apply() }, modifier = Modifier.fillMaxWidth(), colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFDCEAF0))) { Text("＋ 记录一杯水", color = LifeBlue) }
                    } }
                }
                "wardrobe" -> {
                    item { LifeNote("把喜欢的自己，穿进今天的生活里。", "舒服自在，就是今天最好的搭配。", LifePeach) }
                    item { Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                        listOf("日常", "校园", "运动", "亮眼").forEach { style ->
                            Text(style, Modifier.weight(1f).background(if (style == outfitStyle) LifePeach.copy(alpha = .65f) else LifeCard, RoundedCornerShape(18.dp))
                                .border(1.dp, if (style == outfitStyle) LifePeach else Color(0xFFEDE6DE), RoundedCornerShape(18.dp))
                                .clickable { outfitStyle = style; prefs.edit().putString("outfit_style_$date", style).apply() }.padding(vertical = 10.dp),
                                color = LifeBlue, fontSize = 12.sp, textAlign = TextAlign.Center)
                        }
                    } }
                    item { LifePaperCard {
                        LifeSectionTitle("今天穿什么")
                        Text("今日风格 · $outfitStyle", color = LifeBlue.copy(alpha = .72f), fontSize = 12.sp)
                        OutlinedTextField(value = outfit, onValueChange = { outfit = it; saved = false }, modifier = Modifier.fillMaxWidth().height(105.dp), label = { Text("今天的搭配") }, placeholder = { Text("上衣、下装、鞋包……") })
                        Row(horizontalArrangement = Arrangement.spacedBy(7.dp)) {
                            Button(onClick = { prefs.edit().putString("outfit_$date", outfit).putString("outfit_style_$date", outfitStyle).apply(); saved = true }, modifier = Modifier.weight(1f), colors = ButtonDefaults.buttonColors(containerColor = LifePeach)) { Text(if (saved) "已保存" else "保存今日穿搭", color = LifeBlue, fontSize = 12.sp) }
                            Button(onClick = {
                                val choices = prefs.all.filterKeys { it.startsWith("outfit_20") && !it.endsWith("_style_$date") }.values.filterIsInstance<String>().filter(String::isNotBlank)
                                if (choices.isNotEmpty()) outfit = choices.random()
                            }, modifier = Modifier.weight(1f), colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFDCEAF0))) { Text("换一套搭配", color = LifeBlue, fontSize = 12.sp) }
                        }
                    } }
                    item { LifePaperCard {
                        Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.SpaceBetween) {
                            LifeSectionTitle("我的衣橱")
                            Text("＋ 添加衣服", Modifier.clickable { closet = (closet.trimEnd() + if (closet.isBlank()) "" else "\n") + "新衣物" }.padding(5.dp), color = LifeBlue, fontSize = 12.sp)
                        }
                        Row(horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                            listOf("上衣", "下装", "连衣裙", "外套", "鞋子", "包包", "配饰").forEachIndexed { i, label ->
                                Column(Modifier.weight(1f).background(listOf(Color(0xFFF7E5DC), Color(0xFFE2EDF0), LifeSage, Color(0xFFF7E5DC), Color(0xFFE2EDF0), LifeSage, Color(0xFFF7E5DC))[i], RoundedCornerShape(9.dp)).padding(vertical = 6.dp), horizontalAlignment = Alignment.CenterHorizontally) {
                                    Text(listOf("♧", "▱", "♙", "♧", "⌁", "▢", "✦")[i], color = LifeBlue, fontSize = 14.sp)
                                    Text(label, color = LifeBlue, fontSize = 8.sp, textAlign = TextAlign.Center)
                                }
                            }
                        }
                        OutlinedTextField(value = closet, onValueChange = { closet = it; saved = false }, modifier = Modifier.fillMaxWidth().height(110.dp), label = { Text("衣物清单 · 每行一件") }, placeholder = { Text("针织开衫\n牛仔裤\n帆布鞋") })
                        Button(onClick = { prefs.edit().putString("closet_items", closet).apply(); saved = true }, colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFDCEAF0))) { Text(if (saved) "已保存衣橱" else "保存衣橱", color = LifeBlue) }
                    } }
                }
                "ledger" -> {
                    item { LifeNote("把收支理清，也是照顾未来的自己。", "农行、支付宝和微信流水都可以记在这里。", LifeSage) }
                    item { LifePaperCard {
                        LifeSectionTitle("${selectedDate.year}年${selectedDate.monthValue}月 · 收支统计")
                        Text("本月支出", color = LifeBlue.copy(alpha = .74f), fontSize = 13.sp)
                        Text("¥${"%.2f".format(Locale.US, monthlyTotal)}", color = LifeBlue, fontSize = 30.sp, fontWeight = FontWeight.Bold)
                        Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
                            LifeDonut(categoryTotals.take(4), monthlyTotal, Modifier.size(108.dp))
                            if (categoryTotals.isEmpty()) Text("记几笔流水后，这里会显示分类统计。", Modifier.weight(1f), color = LifeInk.copy(alpha = .68f), fontSize = 11.sp)
                            else Column(Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(6.dp)) {
                                categoryTotals.take(4).forEachIndexed { i, pair ->
                                    val share = if (monthlyTotal > 0) (pair.second / monthlyTotal * 100).toInt() else 0
                                    Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                                        Text("● ${pair.first}", color = LifeBlue, fontSize = 10.sp)
                                        Text("$share% · ¥${"%.2f".format(Locale.US, pair.second)}", color = LifeInk, fontSize = 9.sp)
                                    }
                                }
                            }
                        }
                    } }
                    item { LifePaperCard {
                        Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.SpaceBetween) {
                            LifeSectionTitle("最近流水")
                            Text("本月 ${monthLines.size} 笔", color = LifeInk.copy(alpha = .68f), fontSize = 11.sp)
                        }
                        if (monthLines.isEmpty()) Text("还没有流水，记下今天的第一笔吧。", color = LifeInk.copy(alpha = .68f), fontSize = 12.sp)
                        monthLines.take(8).forEach { row ->
                            Row(Modifier.fillMaxWidth().padding(vertical = 4.dp), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.SpaceBetween) {
                                Column(Modifier.weight(1f)) {
                                    Text(row.split("·").getOrNull(1)?.trim()?.ifBlank { "日常支出" } ?: "日常支出", color = LifeBlue, fontWeight = FontWeight.SemiBold, fontSize = 12.sp)
                                    Text(row.take(42), color = LifeInk.copy(alpha = .67f), fontSize = 9.sp)
                                }
                                Text(Regex("¥[0-9]+(?:\\.[0-9]+)?").find(row)?.value ?: "", color = LifeBlue, fontWeight = FontWeight.Bold, fontSize = 13.sp)
                            }
                        }
                    } }
                    item { LifePaperCard {
                        Row(horizontalArrangement = Arrangement.spacedBy(7.dp)) {
                            Button(onClick = { section = "add_expense" }, modifier = Modifier.weight(1f), colors = ButtonDefaults.buttonColors(containerColor = LifePeach)) { Text("✎ 记一笔", color = LifeBlue) }
                            Button(onClick = { section = "add_expense"; receiptPicker.launch(PickVisualMediaRequest(PickVisualMedia.ImageOnly)) }, modifier = Modifier.weight(1f), colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFDCEAF0))) { Text("▣ 导入账单截图", color = LifeBlue, fontSize = 10.sp) }
                        }
                    } }
                }
                "add_expense" -> item { LifePaperCard {
                    LifeSectionTitle("记一笔流水")
                    Button(onClick = { receiptPicker.launch(PickVisualMediaRequest(PickVisualMedia.ImageOnly)) }, colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFDCEAF0))) { Text("▣ 选择账单截图", color = LifeBlue) }
                    if (ocrStatus.isNotBlank()) {
                        Text(ocrStatus, color = LifeBlue, fontWeight = FontWeight.SemiBold, fontSize = 12.sp)
                        if (ocrText.isNotBlank()) Text(ocrText.take(600), color = LifeInk, fontSize = 10.sp, lineHeight = 16.sp)
                        Text("截图仅在本机识别，不会保存原图。", color = LifeInk.copy(alpha = .7f), fontSize = 10.sp)
                    }
                    Row(horizontalArrangement = Arrangement.spacedBy(5.dp)) {
                        listOf("农行", "支付宝", "微信").forEach { source ->
                            Button(onClick = { expenseSource = source }, contentPadding = PaddingValues(horizontal = 10.dp, vertical = 6.dp), colors = ButtonDefaults.buttonColors(containerColor = if (expenseSource == source) LifePeach else LifeSage)) { Text(source, color = LifeBlue, fontSize = 11.sp) }
                        }
                    }
                    OutlinedTextField(value = amount, onValueChange = { amount = it; saved = false }, modifier = Modifier.fillMaxWidth(), label = { Text("金额（元）") }, keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal))
                    OutlinedTextField(value = expenseCategory, onValueChange = { expenseCategory = it; saved = false }, modifier = Modifier.fillMaxWidth(), label = { Text("消费分类") })
                    OutlinedTextField(value = note, onValueChange = { note = it; saved = false }, modifier = Modifier.fillMaxWidth(), label = { Text("备注（可选）") })
                    Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                        Button(onClick = { section = "ledger" }, colors = ButtonDefaults.buttonColors(containerColor = LifeCard)) { Text("取消", color = LifeBlue) }
                        Button(onClick = {
                            val value = amount.toDoubleOrNull()
                            if (value != null && value > 0) {
                                val row = "$expenseSource · ${expenseCategory.ifBlank { "未分类" }} · $note  -¥${"%.2f".format(Locale.US, value)}"
                                transactions = listOfNotNull(row, transactions.takeIf { it.isNotBlank() }).joinToString("\n")
                                prefs.edit().putString("transactions_$date", transactions).apply()
                                amount = ""; note = ""; expenseCategory = ""; saved = true; section = "ledger"
                            }
                        }, colors = ButtonDefaults.buttonColors(containerColor = LifePeach)) { Text(if (saved) "已保存" else "确认保存", color = LifeBlue) }
                    }
                } }
                "water" -> {
                    item { LifeNote("一杯小小的水，也是给自己的温柔。", "慢慢喝，照顾好自己。", Color(0xFFDCEAF0)) }
                    item { LifePaperCard {
                        Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.SpaceBetween) {
                            Column { LifeSectionTitle("今日喝水"); Text("慢慢喝，照顾好自己。", color = LifeBlue.copy(alpha = .74f), fontSize = 12.sp) }
                            Text("$water / 8 杯", color = LifeBlue, fontSize = 20.sp, fontWeight = FontWeight.Bold)
                        }
                        Row(horizontalArrangement = Arrangement.spacedBy(3.dp)) { (0 until 8).forEach { i -> Text(if (i < water) "🥛" else "▱", Modifier.weight(1f), color = LifeBlue, fontSize = 20.sp, textAlign = TextAlign.Center) } }
                        Button(onClick = { if (water < 8) water++; prefs.edit().putInt("water_$date", water).apply() }, modifier = Modifier.fillMaxWidth(), colors = ButtonDefaults.buttonColors(containerColor = LifePeach)) { Text("＋  记录一杯", color = LifeBlue, fontSize = 16.sp) }
                        Text("选择杯量", color = LifeBlue, fontSize = 13.sp, fontWeight = FontWeight.SemiBold)
                        Row(horizontalArrangement = Arrangement.spacedBy(5.dp)) {
                            listOf(200, 300).forEach { ml ->
                                Button(onClick = { cupMl = ml; prefs.edit().putInt("water_cup_ml_$date", ml).apply() }, modifier = Modifier.weight(1f), colors = ButtonDefaults.buttonColors(containerColor = if (cupMl == ml) LifePeach else Color(0xFFF0F2F1))) { Text("$ml ml", color = LifeBlue, fontSize = 11.sp) }
                            }
                            Button(onClick = { customWaterInput = ""; showWaterCustom = true }, modifier = Modifier.weight(1f), colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFF0F2F1))) { Text("自定义", color = LifeBlue, fontSize = 11.sp) }
                        }
                    } }
                    item { LifePaperCard {
                        LifeSectionTitle("⏰  喝水提醒")
                        Row(horizontalArrangement = Arrangement.spacedBy(5.dp)) {
                            listOf("起床后\n07:30", "午餐后\n12:30", "运动后\n18:00").forEachIndexed { i, label ->
                                Column(Modifier.weight(1f).background(listOf(Color(0xFFF8E9D9), Color(0xFFE7EEF0), LifeSage)[i], RoundedCornerShape(13.dp)).clickable {
                                    val key = "water_reminder_$i"; prefs.edit().putBoolean(key, !prefs.getBoolean(key, true)).apply()
                                }.padding(vertical = 10.dp), horizontalAlignment = Alignment.CenterHorizontally) {
                                    Text(listOf("☼", "🍚", "🏋")[i], color = LifeBlue, fontSize = 18.sp)
                                    Text(label, color = LifeBlue, fontSize = 10.sp, textAlign = TextAlign.Center, lineHeight = 15.sp)
                                }
                            }
                        }
                        Text("点按提醒卡可开启或关闭。", color = LifeInk.copy(alpha = .65f), fontSize = 10.sp)
                    } }
                    item { LifePaperCard { Text("💧  今日已喝  ${water * cupMl} ml", color = LifeBlue, fontSize = 18.sp, fontWeight = FontWeight.Bold) } }
                }
            }
        }
        LifeBottomNavigation(active, onSelect = { section = it })
    }
    if (showWaterCustom) AlertDialog(
        onDismissRequest = { showWaterCustom = false },
        title = { Text("自定义杯量", color = LifeBlue) },
        text = { OutlinedTextField(customWaterInput, { customWaterInput = it.filter(Char::isDigit).take(4) }, label = { Text("毫升") }, keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number), singleLine = true) },
        confirmButton = { TextButton(onClick = { customWaterInput.toIntOrNull()?.takeIf { it in 50..2000 }?.let { cupMl = it; prefs.edit().putInt("water_cup_ml_$date", it).apply() }; showWaterCustom = false }) { Text("确定", color = LifeBlue) } },
        dismissButton = { TextButton(onClick = { showWaterCustom = false }) { Text("取消", color = LifeInk) } }
    )
}

@Composable
private fun LifePreviewBanner(section: String, companion: String) {
    val asset = when (section) {
        "diary" -> if (companion == "拾光小队") AnimalDiaryArt else DiaryHeroArt
        "wardrobe" -> if (companion == "拾光小队") AnimalWardrobeArt else WardrobeHeroArt
        "ledger", "add_expense" -> if (companion == "拾光小队") AnimalLedgerArt else LedgerHeroArt
        "water" -> if (companion == "拾光小队") AnimalWaterArt else WaterHeroArt
        else -> HomeHeroArt
    }
    val bitmap = remember(asset) { val bytes = Base64.decode(asset, Base64.DEFAULT); BitmapFactory.decodeByteArray(bytes, 0, bytes.size).asImageBitmap() }
    Image(bitmap, contentDescription = section, modifier = Modifier.fillMaxWidth().height(174.dp), contentScale = ContentScale.Crop)
}

