@Composable
private fun LifeDonut(categories: List<Pair<String, Double>>, total: Double, modifier: Modifier = Modifier) {
    Canvas(modifier) {
        val colors = listOf(LifePeach, Color(0xFF8BCBE5), LifeSage, Color(0xFFF1D2A9))
        if (total <= 0.0 || categories.isEmpty()) drawArc(Color(0xFFEAE6E0), -90f, 360f, false, style = Stroke(width = 18.dp.toPx()))
        else {
            var start = -90f
            categories.forEachIndexed { index, entry ->
                val sweep = (entry.second / total * 360.0).toFloat().coerceAtLeast(2f)
                drawArc(colors[index % colors.size], start, sweep, false, style = Stroke(width = 18.dp.toPx())); start += sweep
            }
        }
    }
}
@Composable
private fun LifeBottomNavigation(selected: String, onSelect: (String) -> Unit) {
    Row(Modifier.fillMaxWidth().background(LifeCard).padding(horizontal = 2.dp, vertical = 5.dp), horizontalArrangement = Arrangement.SpaceEvenly) {
        listOf("today" to "⌂\n今日", "records" to "▤\n记录", "happiness" to "♧\n小确幸", "wardrobe" to "♧\n衣橱", "ledger" to "▤\n流水").forEach { (tab, label) ->
            Text(label, Modifier.weight(1f).clickable { onSelect(when(tab) { "today" -> "home"; "records" -> "diary"; "happiness" -> "water"; "wardrobe" -> "wardrobe"; else -> "ledger" }) }.padding(vertical = 4.dp),
                color = if (selected == tab) LifeBlue else LifeInk.copy(alpha = .7f), fontSize = 10.sp, textAlign = TextAlign.Center, lineHeight = 15.sp)
        }
    }
}


private fun expenseAmount(row: String): Double = Regex("¥([0-9]+(?:\\.[0-9]+)?)").find(row)?.groupValues?.getOrNull(1)?.toDoubleOrNull() ?: 0.0

private fun todayLabel(date: LocalDate): String = "${date.year}年${date.monthValue}月${date.dayOfMonth}日"

private fun ocrAmountCandidates(raw: String): List<Double> {
    val candidates = mutableListOf<Double>()
    raw.lineSequence().forEach { line ->
        val hasCurrencyMarker = line.contains("¥") || line.contains("￥") || line.contains("元")
        if (hasCurrencyMarker) {
            val tokens = line.replace("¥", " ").replace("￥", " ").replace("元", " ")
                .split(Regex("[^0-9.,+-]+"))
            tokens.mapNotNull { it.replace(",", ".").toDoubleOrNull() }
                .filter { it > 0.0 }
                .forEach { candidates.add(it) }
        }
    }
    return candidates.distinct()
}
